from collections import deque

def invertTree(self, root: TreeNode) -> TreeNode:
    if not root:
        return None
    queue = deque([root])
    while queue:
        node = queue.popleft()
        node.left, node.right = node.right, node.left   # swap children
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)
    return root

